import sys
from collections import Counter

def solve():
    n = int(sys.stdin.readline().strip())
    if n == 0:
        print(-1)
        return

    digits = list(map(int, sys.stdin.readline().split()))

    if n == 1:
        if digits[0] == 0:
            print(-1)
        else:
            print(digits[0])
        return

    count = Counter(digits)

    non_zero_counts = []
    for d in range(1, 10):
        if count[d] > 0:
            non_zero_counts.append(d)

    if not non_zero_counts:
        print(-1)
        return

    min_non_zero = non_zero_counts[0]

    has_odd = False
    odd_digit = -1
    for d in range(10):
        if count[d] % 2 == 1:
            has_odd = True
            odd_digit = d
            break

    left_part = []
    for d in range(10):
        c = count[d] // 2
        left_part.extend([d] * c)

    if has_odd:
        left_part.append(odd_digit)

    for i in range(len(left_part) // 2):
        left_part[i], left_part[len(left_part) - 1 - i] = left_part[len(left_part) - 1 - i], left_part[i]

    if not has_odd:
        left_part[-1], left_part[-2] = left_part[-2], left_part[-1]
        left_part.insert(len(left_part) // 2 + 1, left_part[len(left_part) // 2])

    if has_odd:
        for i in range(len(left_part) // 2 + 1, len(left_part)):
            left_part[i] = left_part[len(left_part) - 1 - i]
    else:
        mid = len(left_part) // 2
        for i in range(mid, len(left_part)):
            left_part[i] = left_part[len(left_part) - 1 - i]

    left_str = ''.join(map(str, left_part))
    result = left_str + left_str[::-1]

    print(result)

solve()
